import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0002 (Archived v1): Single Plugin Model — Core Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/archived/0002-handl-platform-composable-host-v1-complete.md","filePath":"vendored/handl/project/adrs/archived/0002-handl-platform-composable-host-v1-complete.md"}`),a={name:`handl/project/adrs/archived/0002-handl-platform-composable-host-v1-complete.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0002-archived-v1-single-plugin-model-—-core-architecture" tabindex="-1">ADR-0002 (Archived v1): Single Plugin Model — Core Architecture <a class="header-anchor" href="#adr-0002-archived-v1-single-plugin-model-—-core-architecture" aria-label="Permalink to “ADR-0002 (Archived v1): Single Plugin Model — Core Architecture”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The platform had overlapping concepts (<code>Plugin</code>, <code>Extension</code>, <code>Component</code>, <code>Target</code>, <code>Library</code>, <code>Kit</code>) that created plumbing and artificial distinctions. The core insight: everything the host loads is a <strong>plugin</strong>. The distinction is only whether a thing accepts rules from others.</p><h2 id="decision-implemented-v1-complete" tabindex="-1">Decision Implemented (v1 Complete) <a class="header-anchor" href="#decision-implemented-v1-complete" aria-label="Permalink to “Decision Implemented (v1 Complete)”">​</a></h2><h3 id="_1-unified-plugin-model" tabindex="-1">1. Unified Plugin Model <a class="header-anchor" href="#_1-unified-plugin-model" aria-label="Permalink to “1. Unified Plugin Model”">​</a></h3><ul><li><strong>Plugin</strong> — the universal component. Every loaded thing is a plugin.</li><li><strong>RuleAcceptor&lt;Rule&gt;</strong> — a sub-trait for plugins that accept contributions.</li><li><strong>Operation</strong> — a marker type for cross-cutting concerns (<code>Format</code>, <code>Lint</code>, <code>Lexer</code>, <code>Parser</code>, <code>Typecheck</code>, <code>Doc</code>, <code>Cli</code>, <code>Lsp</code>, <code>Eval</code>).</li><li><strong>Behavior&lt;Op&gt;</strong> — a single rule that a plugin contributes to an operation for a specific <code>AstNode.kind</code>.</li><li><strong>ContributionContext</strong> — type-safe API for registering plugins and handing rules to <code>RuleAcceptor</code>s.</li></ul><h3 id="_2-removed-legacy-patterns" tabindex="-1">2. Removed Legacy Patterns <a class="header-anchor" href="#_2-removed-legacy-patterns" aria-label="Permalink to “2. Removed Legacy Patterns”">​</a></h3><ul><li>✅ Deleted <code>Extension</code> trait (was pattern for stage-specific plugins)</li><li>✅ Deleted <code>CommandProvider</code> trait (was CLI pattern)</li><li>✅ Deleted <code>Library</code> trait (was library pattern)</li><li>✅ No more hard-coded stage wiring in modern code</li></ul><h3 id="_3-implemented-behavior-lt-op" tabindex="-1">3. Implemented Behavior&lt;Op&gt; <a class="header-anchor" href="#_3-implemented-behavior-lt-op" aria-label="Permalink to “3. Implemented Behavior&amp;lt;Op&gt;”">​</a></h3><ul><li>✅ <code>BasicEvaluator</code> works as <code>RuleAcceptor&lt;Behavior&lt;Eval&gt;&gt;</code></li><li>✅ 30+ <code>impl Behavior&lt;Op&gt;</code> across codebase</li><li>✅ Lint, format, build, compile, typecheck operations all using pattern</li><li>✅ Test evidence of rule contributions and dispatch</li></ul><h3 id="_4-kit-and-host" tabindex="-1">4. Kit and Host <a class="header-anchor" href="#_4-kit-and-host" aria-label="Permalink to “4. Kit and Host”">​</a></h3><ul><li><strong>Kit</strong> — a manifest listing plugins to load</li><li><strong>HostConfig</strong> — in-memory description of which plugins to load, what to exclude, option overrides</li><li><strong>Host</strong> — pure composer with <code>PluginRegistry</code> and <code>OptionsResolver</code></li></ul><h3 id="_5-preserved-exceptions" tabindex="-1">5. Preserved Exceptions <a class="header-anchor" href="#_5-preserved-exceptions" aria-label="Permalink to “5. Preserved Exceptions”">​</a></h3><ul><li><strong>ExecControl trait</strong> — intentionally separate from Behavior&lt;Op&gt; for eval-specific cross-cutting concerns (caching, limits, tracing, sandboxing)</li><li>✅ Used in: <code>plugin-exec-allow</code>, <code>plugin-exec-cache</code>, <code>plugin-exec-counter</code>, <code>plugin-exec-max-calls</code>, <code>plugin-exec-max-depth</code>, <code>plugin-exec-trace</code></li><li>Justified per ADR-0040 §4 as lightweight two-hook pattern for execution control</li></ul><h2 id="implementation-evidence" tabindex="-1">Implementation Evidence <a class="header-anchor" href="#implementation-evidence" aria-label="Permalink to “Implementation Evidence”">​</a></h2><ul><li>✅ <code>Behavior&lt;Op&gt;</code> trait defined in <code>platform/src/plugin_model.rs</code></li><li>✅ All operation types defined and used</li><li>✅ Legacy traits removed (grep for Extension/CommandProvider/Library shows removal comments)</li><li>✅ Modern code uses only Plugin/Behavior&lt;Op&gt; patterns</li><li>✅ Tests verify rule contribution and dispatch</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>✅ No overlapping concepts; everything is a plugin</li><li>✅ Plugins can depend on and provide to other plugins via traits</li><li>✅ Language behavior is composable through Behavior&lt;Op&gt;</li><li>✅ Execution control is a justified exception with proper documentation</li><li>✅ Host is a pure composer, not a concrete type with hard-coded fields</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See also”">​</a></h2><ul><li>ADR-0002 (Remaining) for library plugin conversion roadmap</li><li>ADR-0040 (VM is an operation, not a subsystem) for ExecControl justification</li><li>ADR-0044 (Language as data and runtime split) for data-driven plugins</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};